CREATE TABLE ArrayProcessingData(ArrayProcessingSlotId INTEGER, CabinetId INTEGER, Data BLOB, PRIMARY KEY (ArrayProcessingSlotId, CabinetId) );
CREATE TABLE ArrayProcessingSlots(ArrayProcessingSlotId INTEGER PRIMARY KEY ASC AUTOINCREMENT, SourceGroupId INTEGER, Slot INTEGER, Name VARCHAR, Comment VARCHAR, SessionId BLOB, CreatedOn DATETIME, Flags INTEGER);
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE Controls(ControlId INTEGER PRIMARY KEY ASC AUTOINCREMENT, Type INTEGER, PosX INTEGER, PosY INTEGER, Width INTEGER, Height INTEGER, ViewId INTEGER, DisplayName TEXT, UniqueName TEXT, JoinedId INTEGER, LimitMin REAL, LimitMax REAL, MainColor INTEGER, SubColor INTEGER, LabelColor INTEGER, LabelFont INTEGER, LabelAlignment INTEGER, LineThickness INTEGER, ThresholdValue REAL, Flags INTEGER, ActionType INTEGER, TargetType INTEGER, TargetId INTEGER, TargetChannel INTEGER, TargetProperty VARCHAR, TargetRecord INTEGER, ConfirmOnMsg VARCHAR, ConfirmOffMsg VARCHAR, PictureIdDay INTEGER, PictureIdNight INTEGER, Font BLOB, Alignment INTEGER, Dimension BLOB, LogoId INTEGER);
CREATE TABLE ControlTypes(Type INTEGER PRIMARY KEY ASC,Description VARCHAR);
CREATE TABLE TargetTypes(Type INTEGER PRIMARY KEY ASC,Description VARCHAR);
CREATE TABLE Devices(DeviceId INTEGER PRIMARY KEY ASC AUTOINCREMENT, Model VARCHAR, RemoteIdSubnet INTEGER, RemoteIdDevice INTEGER, Name VARCHAR);
CREATE TABLE DevicesAmplifier(DeviceId INTEGER PRIMARY KEY ASC, InputMode INTEGER, OutputMode INTEGER, FOREIGN KEY(DeviceId) REFERENCES Devices(DeviceId));
CREATE TABLE DevicesMatrix(DeviceId INTEGER PRIMARY KEY ASC, LicenseOptions INTEGER, InputCount INTEGER, OutputCount INTEGER, FOREIGN KEY(DeviceId) REFERENCES Devices(DeviceId));
CREATE TABLE AmplifierChannels(DeviceId INTEGER, AmplifierChannel INTEGER, Name VARCHAR, PRIMARY KEY (DeviceId, AmplifierChannel));
CREATE TABLE MatrixInputs(DeviceId INTEGER, MatrixInput INTEGER, Name VARCHAR, InputMode INTEGER, PRIMARY KEY (DeviceId, MatrixInput));
CREATE TABLE MatrixOutputs (DeviceId INTEGER, MatrixOutput INTEGER, Name VARCHAR, CabinetId INTEGER, CenterOfAudioX REAL, CenterOfAudioY REAL, CenterOfAudioZ REAL, AimingAngleHorizontal REAL, AimingAngleVertical REAL, AimingAngleRotation REAL, PRIMARY KEY (DeviceId, MatrixOutput), FOREIGN KEY (CabinetId) REFERENCES Cabinets(CabinetId));
CREATE TABLE MatrixCoordinateMappings(DeviceId INTEGER, RecordNumber INTEGER, VenueObjectId INTEGER, Flip BOOL, Name VARCHAR, FOREIGN KEY(DeviceId) REFERENCES Devices(DeviceId), PRIMARY KEY (DeviceId, RecordNumber) );
CREATE TABLE MatrixCoordinateMappingPoints(DeviceId INTEGER, RecordNumber INTEGER, PointIndex INTEGER, X REAL, Y REAL, Z REAL, FOREIGN KEY(DeviceId) REFERENCES Devices(DeviceId), PRIMARY KEY (DeviceId, RecordNumber, PointIndex) );
CREATE TABLE Groups(GroupId INTEGER PRIMARY KEY ASC AUTOINCREMENT, Name VARCHAR, ParentId INTEGER, TargetId INTEGER, TargetChannel INTEGER, Type INTEGER, Flags INTEGER);
CREATE TABLE Pictures(PictureId INTEGER PRIMARY KEY AUTOINCREMENT, Name VARCHAR, Comment VARCHAR, PictureData BLOB);
CREATE TABLE ProjectInformation(ProjectName VARCHAR, ProjectDateTime DATETIME, AuthorName VARCHAR, AuthorDateTime DATETIME PRIMARY KEY DESC, Comment VARCHAR, Password VARCHAR, AppVersionR1 VARCHAR, AppVersionArrayCalc VARCHAR, DbVersion VARCHAR);
CREATE TABLE ProjectSettings(Name VARCHAR PRIMARY KEY ASC, Value BLOB);
CREATE TABLE Scenes(SceneId INTEGER PRIMARY KEY ASC AUTOINCREMENT, DeviceId INTEGER, SceneIndexMajor INTEGER, SceneIndexMinor INTEGER, Name VARCHAR, Comment VARCHAR, LastModified DATETIME, Checksum VARCHAR, Flags INTEGER);
CREATE TABLE SceneValues(SceneValueId INTEGER PRIMARY KEY ASC AUTOINCREMENT, SceneId INTEGER, TargetChannel INTEGER, TargetRecord INTEGER, TargetProperty VARCHAR, Value BLOB);
CREATE TABLE Snapshots(SnapshotId INTEGER PRIMARY KEY ASC AUTOINCREMENT, Type INTEGER, Name TEXT, Comment TEXT, CreatedOn DATETIME);
CREATE TABLE SnapshotValues(SnapshotValueId INTEGER PRIMARY KEY ASC AUTOINCREMENT, SnapshotId INTEGER, SnapshotTargetType INTEGER, Value BLOB, TargetId INTEGER, TargetNode INTEGER, TargetProperty VARCHAR, TargetRecord INTEGER);
CREATE TABLE SourceGroups(SourceGroupId INTEGER PRIMARY KEY ASC, Type INTEGER, Name VARCHAR, OrderIndex INTEGER, RemarkableChangeDate INTEGER, NextSourceGroupId INTEGER, ArrayProcessingEnable BOOL, ArraySightId INTEGER, LinkMode INTEGER, Symmetric BOOL, Mounting INTEGER, RelativeDelay REAL);
CREATE TABLE TableVersions(Name VARCHAR NOT NULL PRIMARY KEY ASC, VersionMajor INTEGER, VersionMinor INTEGER);
CREATE TABLE VenueObjects(VenueObjectId INTEGER PRIMARY KEY ASC AUTOINCREMENT, Name VARCHAR, Shape INTEGER, PlaneType INTEGER, Enabled BOOL, Transparent BOOL, Locked BOOL, ListenerHeight REAL, Color INTEGER, PrintColor INTEGER, OriginX REAL, OriginY REAL, OriginZ REAL, RotationX REAL, RotationY REAL, RotationZ REAL, OrderIndex INTEGER, ParentVenueObjectId INTEGER);
CREATE TABLE VenueObjectPoints(VenueObjectId INTEGER ASC,PointIndex INTEGER, X REAL, Y REAL, Z REAL, PRIMARY KEY (VenueObjectId, PointIndex) );
CREATE TABLE Views(ViewId INTEGER PRIMARY KEY ASC AUTOINCREMENT, Type INTEGER, Name VARCHAR, Icon BLOB, Flags INTEGER, HomeViewIndex INTEGER, NaviBarIndex INTEGER, HRes INTEGER, VRes INTEGER, ZoomLevel INTEGER, ScalingFactor REAL, ScalingPosX REAL, ScalingPosY Real, ReferenceVenueObjectId INTEGER);
CREATE TABLE ViewTypes(Type INTEGER PRIMARY KEY ASC, Description VARCHAR);
CREATE TABLE Cabinets(CabinetId INTEGER PRIMARY KEY ASC AUTOINCREMENT, DeviceId INTEGER, AmplifierChannel INTEGER, SpeakerId INTEGER, SourceGroupId INTEGER, PositionIndex INTEGER, OrderIndex INTEGER, HorizontalAngle REAL, VerticalAngle REAL, RotationAngle REAL, PivotAngle REAL, Linked INTEGER, OriginX REAL, OriginY REAL, OriginZ REAL, HornRotationAngle INTEGER);
CREATE TABLE FunctionGroups(FunctionGroupId INTEGER PRIMARY KEY ASC, Name VARCHAR, Mode INTEGER);
CREATE TABLE FunctionGroupsPatch(FunctionGroupId INTEGER, CabinetId INTEGER, PRIMARY KEY(FunctionGroupId, CabinetId), FOREIGN KEY(FunctionGroupId) REFERENCES FunctionGroups(FunctionGroupId), FOREIGN KEY(CabinetId) REFERENCES Cabinets(CabinetId));
CREATE TABLE DeviceRedundancies (DeviceRedundancyId INTEGER PRIMARY KEY ASC, MainDeviceId INTEGER, SpareDeviceId INTEGER, ReadDeviceId INTEGER);
CREATE TRIGGER R1_unasssign_Controls_on_AmplifierChannels_removed AFTER DELETE ON AmplifierChannels FOR EACH ROW BEGIN UPDATE Controls SET TargetId = 0, TargetChannel = -1 WHERE TargetType = 2 AND TargetId = OLD.DeviceId AND TargetChannel = OLD.AmplifierChannel; END;
CREATE TRIGGER R1_unasssign_Controls_on_MatrixInputs_removed AFTER DELETE ON MatrixInputs FOR EACH ROW BEGIN UPDATE Controls SET TargetId = 0, TargetChannel = -1 WHERE TargetType = 2 AND TargetId = OLD.DeviceId AND TargetChannel = OLD.MatrixInput; END;
CREATE TRIGGER R1_unasssign_Controls_on_MatrixOutputs_removed AFTER DELETE ON MatrixOutputs FOR EACH ROW BEGIN UPDATE Controls SET TargetId = 0, TargetChannel = -1 WHERE TargetType = 2 AND TargetId = OLD.DeviceId AND TargetChannel = OLD.MatrixOutput; END;
CREATE TRIGGER R1_unasssign_SceneTransportControls_on_Devices_removed AFTER DELETE ON Devices FOR EACH ROW BEGIN UPDATE Controls SET TargetId = 0, TargetChannel = 0 WHERE TargetType = 7 AND TargetId = OLD.DeviceId; END;
CREATE TRIGGER R1_unasssign_SceneControls_on_Scenes_removed AFTER DELETE ON Scenes FOR EACH ROW BEGIN UPDATE Controls SET TargetId = 0, TargetChannel = -1 WHERE TargetType = 6 AND TargetId = OLD.SceneId; END;
CREATE TRIGGER R1_delete_DevicesAmplifier_on_Devices_removed AFTER DELETE ON Devices FOR EACH ROW BEGIN DELETE FROM DevicesAmplifier WHERE DeviceId = OLD.DeviceId; END;
CREATE TRIGGER R1_delete_DevicesMatrix_on_Devices_removed AFTER DELETE ON Devices FOR EACH ROW BEGIN DELETE FROM DevicesMatrix WHERE DeviceId = OLD.DeviceId; END;
CREATE TRIGGER R1_delete_AmplifierChannels_on_DevicesAmplifier_removed AFTER DELETE ON DevicesAmplifier FOR EACH ROW BEGIN DELETE FROM AmplifierChannels WHERE DeviceId = OLD.DeviceId; END;
CREATE TRIGGER R1_delete_MatrixInputs_on_DevicesMatrix_removed AFTER DELETE ON DevicesMatrix FOR EACH ROW BEGIN DELETE FROM MatrixInputs WHERE DeviceId = OLD.DeviceId; END;
CREATE TRIGGER R1_delete_MatrixOutputs_on_DevicesMatrix_removed AFTER DELETE ON DevicesMatrix FOR EACH ROW BEGIN DELETE FROM MatrixOutputs WHERE DeviceId = OLD.DeviceId; END;
CREATE TRIGGER R1_delete_Groups_on_AmplifierChannels_removed AFTER DELETE ON AmplifierChannels FOR EACH ROW BEGIN DELETE FROM Groups WHERE Type = 1 AND TargetId = OLD.DeviceId AND TargetChannel = OLD.AmplifierChannel; END;
CREATE TRIGGER R1_delete_Groups_on_MatrixInputs_removed AFTER DELETE ON MatrixInputs FOR EACH ROW BEGIN DELETE FROM Groups WHERE Type = 2 AND TargetId = OLD.DeviceId AND TargetChannel = OLD.MatrixInput; END;
CREATE TRIGGER R1_delete_Groups_on_MatrixOutputs_removed AFTER DELETE ON MatrixOutputs FOR EACH ROW BEGIN DELETE FROM Groups WHERE Type = 3 AND TargetId = OLD.DeviceId AND TargetChannel = OLD.MatrixOutput; END;
CREATE TRIGGER R1_delete_SnapshotValues_on_AmplifierChannels_removed AFTER DELETE ON AmplifierChannels FOR EACH ROW BEGIN DELETE FROM SnapshotValues WHERE SnapshotTargetType = 0 AND TargetId = OLD.DeviceId AND TargetNode = OLD.AmplifierChannel; END;
CREATE TRIGGER R1_delete_SnapshotValues_on_MatrixInputs_removed AFTER DELETE ON MatrixInputs FOR EACH ROW BEGIN DELETE FROM SnapshotValues WHERE SnapshotTargetType = 0 AND TargetId = OLD.DeviceId AND TargetNode = OLD.MatrixInput AND (TargetProperty LIKE 'MatrixInput\_%' ESCAPE '\' OR TargetProperty LIKE 'MatrixInputEq\_%' ESCAPE '\' OR TargetProperty LIKE 'SoundObjectRouting\_%' ESCAPE '\' OR TargetProperty LIKE 'Positioning\_Source\_%' ESCAPE '\') ;END;
CREATE TRIGGER R1_delete_SnapshotValues_WithMatrixInputsAsRecords_on_MatrixInputs_removed AFTER DELETE ON MatrixInputs FOR EACH ROW BEGIN DELETE FROM SnapshotValues WHERE SnapshotTargetType = 0 AND TargetId = OLD.DeviceId AND TargetRecord = OLD.MatrixInput AND (TargetProperty LIKE 'MatrixNode\_%' ESCAPE '\' OR TargetProperty LIKE 'ReverbInput\_%' ESCAPE '\') ;END;
CREATE TRIGGER R1_delete_SnapshotValues_on_MatrixOutputs_removed AFTER DELETE ON MatrixOutputs FOR EACH ROW BEGIN DELETE FROM SnapshotValues WHERE SnapshotTargetType = 0 AND TargetId = OLD.DeviceId AND TargetNode = OLD.MatrixOutput AND (TargetProperty LIKE 'MatrixOutput\_%' ESCAPE '\' OR TargetProperty LIKE 'MatrixOutputEq\_%' ESCAPE '\' OR TargetProperty LIKE 'MatrixNode\_%' ESCAPE '\' OR TargetProperty LIKE 'ReverbOutput\_%' ESCAPE '\') ;END;
CREATE TRIGGER R1_delete_MatrixCoordinateMappings_on_DevicesMatrix_removed AFTER DELETE ON DevicesMatrix FOR EACH ROW BEGIN DELETE FROM MatrixCoordinateMappings WHERE DeviceId = OLD.DeviceId; END;
CREATE TRIGGER R1_delete_MatrixCoordinateMappings_on_VenueObjects_removed AFTER DELETE ON VenueObjects FOR EACH ROW BEGIN DELETE FROM MatrixCoordinateMappings WHERE VenueObjectId = OLD.VenueObjectId; END;
CREATE TRIGGER R1_delete_MatrixCoordinateMappingPoints_on_MatrixCoordinateMappings_removed AFTER DELETE ON MatrixCoordinateMappings FOR EACH ROW BEGIN DELETE FROM MatrixCoordinateMappingPoints WHERE DeviceId = OLD.DeviceId AND RecordNumber = OLD.RecordNumber; END;
CREATE TRIGGER R1_update_Groups_on_LoudspeakerTarget_changed AFTER UPDATE OF DeviceId, AmplifierChannel ON Cabinets FOR EACH ROW BEGIN UPDATE Groups SET TargetId = NEW.DeviceId, TargetChannel = NEW.AmplifierChannel WHERE TargetId = OLD.DeviceId AND TargetChannel = OLD.AmplifierChannel AND Type = 1;	END;
CREATE TRIGGER R1_update_Controls_on_LoudspeakerTarget_changed AFTER UPDATE OF DeviceId, AmplifierChannel ON Cabinets FOR EACH ROW BEGIN UPDATE Controls SET TargetId = NEW.DeviceId, TargetChannel = NEW.AmplifierChannel WHERE TargetId = OLD.DeviceId AND TargetChannel = OLD.AmplifierChannel AND ActionType = 1 AND TargetType = 2; END;
CREATE TRIGGER R1_update_ControlsGui_on_LoudspeakerTarget_changed AFTER UPDATE OF DeviceId, AmplifierChannel ON Cabinets FOR EACH ROW BEGIN UPDATE Controls SET TargetId = NEW.DeviceId WHERE TargetId = OLD.DeviceId AND TargetChannel = 0	AND ActionType = 1 AND TargetType = 2; END;
CREATE TRIGGER R1_delete_Scenes_on_DevicesMatrix_removed AFTER DELETE ON DevicesMatrix FOR EACH ROW BEGIN DELETE FROM Scenes WHERE DeviceId = OLD.DeviceId; END;
CREATE TRIGGER R1_delete_SceneValues_on_Scenes_removed AFTER DELETE ON Scenes FOR EACH ROW BEGIN DELETE FROM SceneValues WHERE SceneId = OLD.SceneId; END;
CREATE TRIGGER R1_delete_SceneValues_on_MatrixInputs_removed AFTER DELETE ON MatrixInputs FOR EACH ROW BEGIN DELETE FROM SceneValues WHERE SceneValueId IN(select sv.SceneValueId FROM devicesmatrix dm INNER JOIN Scenes s ON s.deviceid = dm.deviceid INNER JOIN SceneValues sv on s.sceneid = sv.sceneid WHERE sv.TargetChannel = OLD.MatrixInput AND dm.deviceid = OLD.deviceid); END;
